package diff_test

import (
	"os"
	"path/filepath"
	"strings"
	"testing"

	"goodkind.io/pr-review-agent/internal/diff"
	"goodkind.io/pr-review-agent/internal/domain"
)

func TestCollectorPreservesRemovedSourceForClassification(t *testing.T) {
	directory := t.TempDir()
	largeGitCommand(t, directory, "init", "--quiet")
	removed := map[string]string{
		"generated.go": "// Code generated by fixture. DO NOT EDIT.\n\npackage generated\n\nconst Value = 1\n",
		"generated.sh": "#!/usr/bin/env bash\n# Code generated by fixture. DO NOT EDIT.\n\n  echo 'generated'\n# End of generated source",
		"source.txt": "--- original source line\n\n+ another source line\n",
	}
	for path, content := range removed {
		writeRecoveryFile(t, directory, path, content)
	}
	writeRecoveryFile(t, directory, "consumer.go", "package consumer\n")
	largeGitCommand(t, directory, "add", "--all")
	largeGitCommit(t, directory, "Create source for classification")
	base := domain.HeadSHA(strings.TrimSpace(largeGitCommand(t, directory, "rev-parse", "HEAD")))
	for path := range removed {
		if err := os.Remove(filepath.Join(directory, path)); err != nil {
			t.Fatal(err)
		}
	}
	const currentContent = "package consumer\n\nconst Value = 2\n"
	writeRecoveryFile(t, directory, "consumer.go", currentContent)
	largeGitCommand(t, directory, "add", "--all")
	largeGitCommit(t, directory, "Remove generated source and update its consumer")
	head := domain.HeadSHA(strings.TrimSpace(largeGitCommand(t, directory, "rev-parse", "HEAD")))
	source := &repositorySource{directory: directory, base: base, head: head, patchMode: "complete"}
	input, err := diff.NewCollector(source).Collect(t.Context(), recoveryRef(head), recoveryPullRequest(source))
	if err != nil {
		t.Fatal(err)
	}
	if len(input.Files) != len(removed)+1 {
		t.Fatalf("Collected file count = %d; expected %d", len(input.Files), len(removed)+1)
	}
	for _, file := range input.Files {
		if !file.CoverageComplete {
			t.Fatalf("The actual Git change for %s must have complete evidence.", file.Path)
		}
		if file.Status != "removed" {
			if file.ClassificationContent() != currentContent {
				t.Fatal("Classification must use current source for the surviving consumer.")
			}
			continue
		}
		if content := file.ClassificationContent(); content != removed[file.Path] {
			t.Fatalf("Classification content for %s = %q; expected the exact removed source %q", file.Path, content, removed[file.Path])
		}
		if file.CurrentContent != "" || len(file.ChangedRightLines) != 0 {
			t.Fatal("Removed source evidence must not create current source or right-side anchors.")
		}
	}
}
